// Palit decisions: the design history behind the Decisions tab.
// Append-only, like the archive: add new entries at the end, never delete or renumber.
// To correct an entry, add a new one that points back to it with `revises`.
// Filling in a missing reason later is fine: set `why`, `whyStatus` and `whyAdded`.
//
// whyStatus:
//   "noah"    Noah's own reason, in his words or logged and approved by him
//   "rule"    the reason comes from a project rule (CLAUDE.md, an approved decision)
//   "agent"   only an agent's reasoning so far; Noah hasn't given his
//   "missing" no reason recorded yet; `ask` holds the question to put to Noah
//
// video: which part of the final video an entry could feed. Tags match the
// blocks in video.js: open, audience, landscape, opinion, demo, process,
// rock:A … rock:E (the big rock candidates in compass.js), visual, next.
//
// Paths in `links` and `images` are relative to design/history/.

