      title: "Research: naming, collecting and creativity",
      video: ["opinion", "process"],
      summary: "The strongest support for human-first naming: in three studies, people who named a product felt more ownership of it and valued it more (Stoner et al., 2018). People also remember what they generate themselves better (a meta-analysis of 86 studies), and things marked as theirs. The key caution: words can pull a visual memory toward its category, so the name is the handle and the meaning, and the swatch and hex keep the color exact. That backs A27. On collecting: designers keep collections and talk through their sources, varied examples lead to more varied ideas, and early evidence suggests AI images narrow exploration. No study shows an archive itself makes people more creative, so the video shouldn't claim it.",
      why: "Noah asked for strong, reliable evidence that naming something yourself makes it yours, and that collecting during ideation matters.",
      whyStatus: "noah",
      whySource: "Noah, in chat",
      status: "done",
      by: "Claude Code, with a research agent",
      links: [{ label: "Evidence", href: "#research/evidence" }]
