      summary: "Verified numbers for Noah's three claims. Your own eye: with AI ideas, stories were rated 8.1% more novel but became more alike (Science Advances, 2024), and students who leaned on unrestricted GPT-4 scored 17% lower once it was gone (PNAS, 2025). The process: expert designers spent more time scoping problems and gathering information than students (2007), and they develop problem and solution together, which backs working holistically. Naming: people who named a product felt more ownership and valued it more (2018); mug owners asked about two and a half times what buyers offered (1990). No study tests naming colors or silly names, and the strongest naming effects came from names that fit and were creative.",
