      to: "Six more desks for v3 and the animated desktop, built the same way over the iMac Silver wallpaper: Hokusai's Great Wave on the Met's page with a detail in Preview (CC0), Grand Prismatic Spring (National Park Service, public domain), Jardin Majorelle beside Wikipedia's Majorelle Blue, WØRKS's home page, a public Are.na color channel, and Sip's home page as a nudge. Noah's palit ideation channel is private, so the Are.na desk uses a public one; his own can replace it. Pinterest and Cosmos wait for screenshots Noah takes while signed in, in design/v2/screens/incoming/. Crocoite and brownstone stay first and the new desks have no seeds, so today's colors and v3's numbering don't change. They're for the demo and the mid-journey archive, not the new-user and longtime-user edge cases. Each desk has regions, so a pick anywhere names its app, place, title and URL, and a few spots for the playback.",
