      from: "On the specimen card, Also from here was a 22px strip that stopped at 220px, and a palette's strip was 14px tall and 112px wide at the right end of its row, lined up with nothing. The scratch pad was written at 13px.",
      to: "The standard for a strip of colors beside a label, in v3 and the design system's level 6: as tall as the label's capitals (1cap) and sitting on its baseline. Also from here runs to the card's edge, or halfway across the value column when it holds one color. A palette's row splits the value column in two with a 12px gap: the name on the left, the strip on the right half, ending at the edge, so it starts where a single color ends. The scratch pad goes to 11 (what's said about a color, A97), on rules 18px apart. Behind ?cfg=polish:off, the card looks as it did. A palette name that's longer than half the column now wraps to two lines.",
      why: "the also from here should match the height of the font to the left of it, and should span until the edge, unless there is just one, in which case it should span half. The palette beside it sshould be more mindful of the column spacing on the card. Make this a standard\n\nScratchpad text could be a little subtler?",
