      to: "Five originals downloaded on Noah's yes, into design/v2/screens/sources/ (kept off the public site): the crocoite photo from Commons (1923 by 1301), Harlem's brownstones (3707 by 3060), the Park Service's Grand Prismatic Spring from June 22, 2006 (3504 by 2336; the first Commons file Claude picked was a different photo and wasn't used), Jardin Majorelle (3216 by 2136) and the Met's Great Wave (3859 by 2594). Each was measured onto its desk against the desk's own pixels. When a card opens, v3 cuts the same square from the original: crocoite 521 pixels, the Great Wave 621, brownstone 1005. Near a photo's edge the square stays inside the photo instead of running onto the window. Off the public site, or for colors picked off a photo, the desk's crop stays.",
      why: "And - could we use the highest resolution photos possible for the color card sampling pictures?\n\nYes, download all five originals (about 19 MB) and use them for the card's samples.",
