      title: "The video's timing comes from the script: each line takes as long as it takes to say",
      video: ["process"],
      from: "Each section had a fixed length and each line a fixed beat, so when Noah's lines got longer or shorter, the picture kept its own time. His demo-2 says the loupe and the keep in one line, so every later demo line played one moment behind.",
      to: "Each line takes as long as its words, at about 2.8 a second, a little faster than a normal pace, and the picture waits for it. Every section's animation is warped so each moment lands on its line, and v3's playback gets the same beats, moving faster or slower within a moment to keep up. The script page shows the moment each line plays over (which Noah can change) and when it's said. Deleting a line fast-forwards its moment; deleting every line in a section cuts the section and its statement. The demo's lines now follow Noah's order, and the subtitles download on the same clock. With his lines as written, the cut is 9:01.",
      why: "And be wary of the script. I will be changing it, and I've noticed that when it gets longer or shorter in certain sections, or when I remove certain sections in general, the flow of the beat of the video gets off. The demo is playing one part while I'm still saying another part, which shouldn't be an issue. Just refer to my script and guess how long we'll be speaking for. We'll be speaking at a pretty normal pace, maybe just a little bit faster than normal, to talk. Consider that whilst you're still building the video",
      whyStatus: "noah",
      whySource: "Noah, in chat",
      status: "built",
