      to: "Each of the 46 stills has a three-second moving preview that plays while you point at it, or while it has the keyboard's focus, and stops when you leave. Each preview leads into its still's moment. Charts and reels are drawn frame by frame from viz.html; the animated desktop is filmed from v3's own playback. They're MP4s next to the stills, 852 KB in all. `node design/history/shots/video/previews.mjs http://localhost:8790` makes them after capture.py, and v3 exposes `PalitV3.clock()` so the frames line up with its playback.",
