      to: "Smooth fades are the default again. Opacity only, on v3's ease, each word or piece fading in over about 0.4 seconds after the one before. The words in a statement, the brief's lines, the reels' quotes and persona cards, and the charts' pieces all fade. ?motion=clunk still shows the quick version. The intro is said quickly (3.2 words a second) but not squeezed, and no line in the video is on screen for less than 1.2 seconds. The intro runs about 16.6 seconds with Noah's lines, and the video 9:15. Once the footage is in, it sets the intro's real timing; to get under 10 seconds, the lines need trimming.",
