      why: "try to find a direction and stick to it, so we don't backtrack. ... Be mindful of my feedback not just specific to the section its written for, but holistically, so that we can build a visual language/taste regarding how the video feels. (m009) lets instead of the droplet, adopt the cursor quickly dragging a box around the highlighted word - feels more on-theme and professional. can we have a subtle fade with the slide up? Both in and out, making it feel more fluid and pro (m018) not loving how the colored words shrink then go into where the boxes are - can we just drop/fade them and have them re-appear as the boxes? Will be cleaner.\n\nAll these instances of components either just fading in, or having a slide in is not what I want - I want a consistent way they appear with a mix of both, being elegant and pro looking.\n\nLoving how it times with the scrip - we may have to slightly tune the timing with the audio recordings.",
