      why: "(m001) lets add a heyclicky styled, subtle color grading that makes our footage feel fresh and friendly - warmer. I also want a slight film look, similar to heyclicky's videos. I also want a subtle fisheye lens just to the walk-in, it'll really add to the atmosphere. Make Cooper Union a little bigger, and rethink the specific moment of the clip you chose for us going up the stairs. Apply this to our interview/outro footage as well. (m002) we shouldn't see the moment we stand before we sit, when this clip plays, we should already be on the way down, making it a quick transition from the walk-in. Refer to the walk-in notes for the coloring and effects.",
