      area: "video",
      title: "The demo, round two: an app that answers the cursor, momentum, and nothing that snaps",
      video: ["demo"],
      revises: 230,
      from: "Round one's choreography (entry 230): the cursor didn't make anything react, Spectrum turned in eased steps, the bumps snapped, and closing the window flashed the view under it.",
      to: "In the demo, everything with a hover state now answers the drawn cursor the way it would a real mouse: tiles widen and show their number, buttons and letters darken, Today underlines. Spectrum's scroll is a push that coasts to a stop with momentum, twice, landing exactly on the color to rename. The palette's and the mark's bumps swell and settle over 800 ms with no snap. Today opens place by place: the day, each place's words, its photo settling, then its colors. Things rise as they come in, the card included, a little slower in the demo than in the app. The note in the scratch pad has a small typo, a pause and a correction. The menu bar's clock is drawn live, so the close-up on the mark is sharp at any zoom. Closing the window no longer flashes the colors behind the share card, a fix that also applies in the app. Deep dive 2's playback gets the same treatment, on its own beats. Done by a subagent; the camera's tweens and the rounded window are the player's (entry 239).",
      why: "(m022) The zoom out is so janky. Lets make it smooth, and not too sudden. Buffer it just slightly, you know? I also don't know why we're working with a screenshot of the prior version - redo the demo recording if needed, to make it as crisp and clean as possible with these changes. (m023) This looks great, I think the keybinds could fade out a little smoother, in the order you click them in. They should bump slightly also in the order you use them in, not too harshly though.\n\nLooks great though. Lets keep this as we rebuild this demo section (m024) Good beats and timing, but the initial bump for the color coming into the side chip feels a little off? Can we make it more elegant, with a smoother animation? Feel free to take slightly more time animating the bumps.\n\nAlso, just in general for this section, the desktop is like a square. Can it be rounded a little, and be windowed by the white background slightly? Just so it looks equal when we zoom out of the window. (m025) great, just refer to prior notes about movement, keybinds, bumps, and whatnot (m026) The demo doesn't act like the app - the blocks should be reactive whenever you hover over them, even slightly, which should be reflected. Make it subtle, but true to how our app works now. The transition to opening the today page looks pretty good, but I feel as though the animation could be just a little bit more fancy and slower (m027) So good, just refer to prior notes about keybind bumps and the slowing down/decorating of the appear animations - just slightly to make it feel more elevated and timed (m028) specturm scroll still doesn't feel very human scroll like, lets make it more smooth, but authentic. The zoom for naming is awesome.\n\nThe appear animation could again, be slightly more elevated, slowed, and decorated/timed.\n\nRefer to prior notes about keybind bumps too. (m029) I think the color card could slightly slide up when it fades in, just to give it a more elevated look. Loving the zoom for the scratchpad, looks good. Can we make it reflect human typing just a little more? Maybe even a semi-typo, a quick delete, then correction? I'm talking maybe 2 or 3 letters. (m030) looks good, lets just be mindful of smoothing the camera movement and zooms, which goes for all sections of this video - lets be smooth/elegant when we can, especially when we need quick pans and movements. (m031) Not sure what the animation is in the background when we close the palette window, something weird happens with the colors when you go to close the palette window. Good camera zooms that make the feature feel coherent we could even zoom in slightly more, before zooming out.",
