      to: "The player gives every motion and desktop section one exit: in its last 0.42 seconds the whole scene slides up 64px, faster and faster, fading as it goes. After its statement, a section rises 22px into place as it fades in, so the next section never flashes on. Filmed sections still cut on the beat, and a section can say exit: false or enter: false. The cursor comes to each highlighted word from a new direction, in turn: bottom right, top left, bottom left, top right, counting the statements and the highlights in the charts between them. A statement's box leaves with its word, sliding up as the text fades (the charts' boxes already did). Rules 11 and 12 in docs/11-motion-kit.md; the deep dives and the closing get them too.",
      why: "(m008) When the word mark kind of disappears from the screen, right now it just fades and moves a little up. I think that could be a little bit accentuated. We could have it just slide up a little quicker and fade out in that process. It should be kind of subtle but also kind of animated. Keep that in mind for just all future, scenes and sections, things that kind of lead to other things, should always end with some sort of fleeting motion, even if it's subtle and it fades out quickly, it should lead with motion. (m009) Amazing. Exactly what we need. I think just for future reference, whenever an overlay is shown, I think it would be awesome, if we could have the box slide up with the text, when it fades, and I think the cursor could come from different directions to the highlighted word. So for instance, right now it's coming from the bottom right to the word brief, maybe on the next one it comes from the top left, then bottom left, top right, just different directions so we keep it new every single time. But other than that, really good. (m010) Great. Just. Refer to the feedback about the cursor coming from different directions. Looks amazing. (m017) Refer to the cursor change. (m021) I'm seeing kind of a pixel glitch, or sorry, just a screen glitch of seeing the next section at the very end of this recording. Maybe that's just because it fades out, and the screen recording is a little bit faulty, but let's just make sure that there isn't any glitching going on throughout the video. Looks really good. Again, just refer to the cursor feedback and how the block follows the word out.",
