      to: "design/video/export.mjs records every section of the player frame by frame at 1920 by 1080 and 60 frames a second, on the workshop's virtual clock, and joins them end to end with no gap or overlap: 33,696 frames, 9:21.6. It mixes the sound the way the player plays it. The house track runs from the start to its own end and again for the outro. The calm track runs from deep dive 1's statement to the outro, coming round on deep dive 3's statement. Both dip under every line, at the levels set in Noah's player (house 0.35, calm 0.39), with the intro's and outro's voice takes. Subtitles are off, as in Noah's player, and there are no speaker chips (entry 263). The film is design/video/footage/exports/palit-cut-20261021-0231.mp4, off the public site with the footage. Every seam between sections was checked frame by frame. Not in it yet: the voiceover, which isn't recorded, and v3's own sounds (the keep's wood).",
