      from: "problem-3 was Daeun's, with no take, and the sofa thumped under \u201cWe're designers\u201d as Noah and Daeun sat down.",
      to: "problem-3 is Noah's, with his take (word for word the script), so all 49 voiceover lines have takes, and the film is 9:21.1. In the intro, from 0.38 to 0.86 s, the sound crossfades to a copy with nothing under 220 Hz: the cushions' boom is 11 to 20 dB down, and the voice above it stays (footage/grade/dethump.sh; the file before it is footage/rough/v3/intro-before-dethump.mp4; a before and after is design/video/audio/voice/intro-sitdown-before-after.wav).",
