      revises: 280,
      from: "Every take went through the same cleaning: strong denoising, a steep 90 Hz low cut, a 250 Hz cut and pauses 25 dB down. Daeun's takes stayed dark (her 8 kHz sat 8 dB under her 1 kHz), Noah's lost their body (125 Hz level with 1 kHz), and the pauses were dead air. The sofa still thumped before \u201cWe're designers\u201d, and the chip's and the mark's bumps were silent.",
      to: "Each voice is cleaned its own way (lines.py CLEAN, clean.py's new options). Both are denoised more gently (9 and 3, not 16 and 6), and their pauses go 15 dB down, not 25. Noah gets a 70 Hz low cut, no 250 Hz cut, +2 dB of warmth at 160 Hz, presence and air: his 125 Hz is back to +2.4 dB against 1 kHz. Daeun's EQ was picked from three tried on her takes: 4 dB less mud at 320 Hz, +4 dB at 2.5 and 5 kHz, and a +6 dB shelf from 8 kHz with a light de-esser. Her 2, 4 and 8 kHz now sit at -2.9, -2.9 and -4.4 dB against 1 kHz (Noah's -2.6, -5.2, -2.6), and her loudest \u201cs\u201d sounds are still at or under his. Every line is -15.7 to -16.4 LUFS. A steady room tone (ambience/room-tone.wav, soft pink noise from 70 Hz to 6.5 kHz, looping) sits 28 dB down from the splash to the end of the horizon, so the pauses aren't dead. The intro's sound is silent until 0.42 s and fades in by 0.48, just before \u201cWe're\u201d (footage/grade/dethump.sh). The chip's bump has a soft drop and the mark's a soft pluck (Kenney's drop_001 and pluck_001, at -22 and -23 dB). The music stays as it is. With the new trims the film is 9:18.2.",
      why: "1. Um, 1st thing I notice, Dawn's lines sound a little muffled. Could we kinda fix that? My voice, on the other hand, sounds a little tiny. I think there's just a lot of background removal happening. That's why it sounded like that. I want it to sound kind of crisp and high quality. Maybe kind of static noise in the walk-in could help with that. Potentially just to ease that. Yeah, to ease that. Sound? I also think that we could also just cut off or fade in the sitting down. Because the noise we make when we sit down still is a little bit jarring and a little loud. So what if we just faded to match exactly when the 1st line starts.\n\nThe bumps for the palette chip and the icon at the top should have a subtle sound.\n\nI'm actually quite happy with the music now - just the voiceovers should be tuned",
